// HostServiceClient is the client API for HostService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// HostService is served by the HOST and dialed by plugins for reverse calls.
type HostServiceClient interface {
	// CallAction forwards a platform API call (e.g. OneBot v11 call_action).
	CallAction(ctx context.Context, in *CallActionRequest, opts ...grpc.CallOption) (*CallActionResponse, error)
	// SendMessage sends a message chain to a session (proactive/reactive send).
	SendMessage(ctx context.Context, in *SendMessageRequest, opts ...grpc.CallOption) (*Empty, error)
	// RecallMessage recalls an already-sent message by platform message id.
	RecallMessage(ctx context.Context, in *RecallMessageRequest, opts ...grpc.CallOption) (*Empty, error)
	// GetConfig returns the plugin's persisted config (plugins/<name>/config.json).
	GetConfig(ctx context.Context, in *GetConfigRequest, opts ...grpc.CallOption) (*GetConfigResponse, error)
	// SetConfig persists the plugin's config (plugins/<name>/config.json).
	SetConfig(ctx context.Context, in *SetConfigRequest, opts ...grpc.CallOption) (*Empty, error)
	// ChatLLM calls the host's default chat LLM provider and returns the reply.
	ChatLLM(ctx context.Context, in *ChatLLMRequest, opts ...grpc.CallOption) (*ChatLLMResponse, error)
	// React adds an emoji reaction to a message (platforms supporting it).
	React(ctx context.Context, in *ReactRequest, opts ...grpc.CallOption) (*Empty, error)
	// TextToImage renders text into an image (host t2i engine) and returns the
	// PNG bytes (base64). The plugin can then send it as an Image component.
	TextToImage(ctx context.Context, in *TextToImageRequest, opts ...grpc.CallOption) (*TextToImageResponse, error)
	// HtmlRender renders an HTML template + data into an image via the host
	// (t2i remote preferred, local gg fallback). Returns PNG bytes (base64).
	HtmlRender(ctx context.Context, in *HtmlRenderRequest, opts ...grpc.CallOption) (*HtmlRenderResponse, error)
	// ── 会话管理（对齐 Python AstrBot conversation_manager）──
	// 取会话当前 ID（umo 无会话时返回空串）。
	GetCurrConversationID(ctx context.Context, in *ConversationIDRequest, opts ...grpc.CallOption) (*ConversationIDResponse, error)
	// 新建会话（设为当前）并返回其 ID。
	NewConversation(ctx context.Context, in *NewConversationRequest, opts ...grpc.CallOption) (*ConversationIDResponse, error)
	// 按 umo+cid 取会话（create_if_not_exists 时不存在则新建）。
	GetConversation(ctx context.Context, in *GetConversationRequest, opts ...grpc.CallOption) (*ConversationResponse, error)
	// 列出某 umo 的全部会话（无 umo 时列出全部）。
	GetConversations(ctx context.Context, in *GetConversationsRequest, opts ...grpc.CallOption) (*ConversationsResponse, error)
	// 删除会话（按 umo+cid；cid 空时删除当前会话）。
	DeleteConversation(ctx context.Context, in *DeleteConversationRequest, opts ...grpc.CallOption) (*Empty, error)
	// 切换当前会话（设置 umo 的 current cid）。
	SwitchConversation(ctx context.Context, in *SwitchConversationRequest, opts ...grpc.CallOption) (*Empty, error)
	// 更新会话标题。
	UpdateConversationTitle(ctx context.Context, in *UpdateConversationTitleRequest, opts ...grpc.CallOption) (*Empty, error)
	// 更新会话绑定的人格。
	UpdateConversationPersonaID(ctx context.Context, in *UpdateConversationPersonaRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 人格管理（对齐 Python AstrBot persona_manager）──
	// 取全部人格。
	GetPersonas(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*PersonasResponse, error)
	// 取默认人格（按 umo 解析默认人格 id/name）。
	GetDefaultPersona(ctx context.Context, in *GetDefaultPersonaRequest, opts ...grpc.CallOption) (*PersonaResponse, error)
	// 取文件夹树（嵌套结构）+ 全部人格。
	GetPersonaTree(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*PersonaTreeResponse, error)
	// 解析当前生效人格（会话/规则/默认的优先级合并）。
	ResolveSelectedPersona(ctx context.Context, in *ResolvePersonaRequest, opts ...grpc.CallOption) (*ResolvePersonaResponse, error)
	// ── Provider 管理（对齐 Python AstrBot provider_manager）──
	// 列出全部 provider（按能力类型过滤，空=全部）。
	ListProviders(ctx context.Context, in *ListProvidersRequest, opts ...grpc.CallOption) (*ProvidersResponse, error)
	// 取某 umo 当前使用的 provider（按能力类型）。
	GetUsingProvider(ctx context.Context, in *GetUsingProviderRequest, opts ...grpc.CallOption) (*ProviderResponse, error)
	// 设置某 umo 的当前 provider。
	SetProvider(ctx context.Context, in *SetProviderRequest, opts ...grpc.CallOption) (*Empty, error)
	// 取 provider 的模型列表。
	GetProviderModels(ctx context.Context, in *GetProviderModelsRequest, opts ...grpc.CallOption) (*ProviderModelsResponse, error)
	// ── 插件/Star 管理（对齐 Python AstrBot star_manager）──
	// 列出全部已安装插件（Star 元数据）。
	GetPluginRegistry(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*StarsResponse, error)
	// 按插件名取 Star 元数据。
	GetStar(ctx context.Context, in *GetStarRequest, opts ...grpc.CallOption) (*StarResponse, error)
	// 启用/禁用插件。
	SetPluginEnabled(ctx context.Context, in *SetPluginEnabledRequest, opts ...grpc.CallOption) (*Empty, error)
	// 安装插件（git/url 源）。
	InstallPlugin(ctx context.Context, in *InstallPluginRequest, opts ...grpc.CallOption) (*Empty, error)
	// UninstallPlugin 卸载插件。
	UninstallPlugin(ctx context.Context, in *UninstallPluginRequest, opts ...grpc.CallOption) (*Empty, error)
	// ListCommandDescriptors 返回全部插件的命令描述符（含子命令/组/别名/
	// 权限/描述）。子进程架构下插件自身进程的 star 注册表只含自己的
	// handler，helps 类插件需经宿主查询全局指令列表。
	ListCommandDescriptors(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*CommandDescriptorsResponse, error)
	// ListPlatforms 返回全部已加载平台实例元数据（id/type/name/display_name/
	// config），供插件（如群分析类）发现平台并创建跨进程 bot 代理。
	ListPlatforms(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*PlatformsResponse, error)
	// ── 会话等待（SessionWaiter 跨进程喂入）──
	// 插件注册"等待某 umo 的下一条消息"（session_waiter.register_wait）。
	// 宿主收到该 umo 的消息时经 PluginService.FeedSessionWait 推送事件。
	RegisterSessionWait(ctx context.Context, in *RegisterSessionWaitRequest, opts ...grpc.CallOption) (*RegisterSessionWaitResponse, error)
	// 插件注销等待（会话结束/超时）。
	UnregisterSessionWait(ctx context.Context, in *UnregisterSessionWaitRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 桥接钩子（botpy/telegram 等兼容层）──
	RegisterBridgeHook(ctx context.Context, in *BridgeHookRequest, opts ...grpc.CallOption) (*Empty, error)
	UnregisterBridgeHook(ctx context.Context, in *BridgeHookRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 大文件 Blob 存储（P0-2）──────────────────────────────
	// 插件把大于 inline 阈值（1MB）的二进制交给宿主持久化，拿到一个受控
	// handle；后续经 ReadBlob 分块读取。宿主统一管理生命周期（TTL/GC），
	// 插件只传 handle，绝不传任意文件路径（防路径穿越）。
	CreateBlob(ctx context.Context, in *CreateBlobRequest, opts ...grpc.CallOption) (*CreateBlobResponse, error)
	// ReadBlob 按 offset/limit 分块读，避免单次大缓冲。
	ReadBlob(ctx context.Context, in *ReadBlobRequest, opts ...grpc.CallOption) (*ReadBlobResponse, error)
	GetBlobInfo(ctx context.Context, in *GetBlobInfoRequest, opts ...grpc.CallOption) (*GetBlobInfoResponse, error)
	ReleaseBlob(ctx context.Context, in *ReleaseBlobRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 技能（Skills，宿主 internal/skills 能力 → 插件可读可改）──
	// ListSkills 返回宿主技能管理器中的全部技能（SkillInfo JSON 列表）。
	ListSkills(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*SkillsResponse, error)
	// SetSkillActive 启用/禁用指定技能。
	SetSkillActive(ctx context.Context, in *SetSkillActiveRequest, opts ...grpc.CallOption) (*Empty, error)
	// DeleteSkill 删除指定技能。
	DeleteSkill(ctx context.Context, in *DeleteSkillRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 平台消息历史（宿主 db platform_message_history 表 → 插件可读可改）──
	// GetPlatformMessageHistory 按平台/用户取最近 n 条消息记录。
	GetPlatformMessageHistory(ctx context.Context, in *GetPMHistoryRequest, opts ...grpc.CallOption) (*PMHistoryRecordsResponse, error)
	// InsertPlatformMessageHistory 插入一条平台消息记录。
	InsertPlatformMessageHistory(ctx context.Context, in *InsertPMHistoryRequest, opts ...grpc.CallOption) (*PMHistoryRecordResponse, error)
	// UpdatePlatformMessageHistory 更新一条记录（content / llm_checkpoint_id）。
	UpdatePlatformMessageHistory(ctx context.Context, in *UpdatePMHistoryRequest, opts ...grpc.CallOption) (*Empty, error)
	// DeletePlatformMessageHistory 按 ID 删除一条记录。
	DeletePlatformMessageHistory(ctx context.Context, in *DeletePMHistoryRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 知识库（对齐宿主 internal/knowledgebase/manager.go）──
	// KBRetrieve 检索知识库：按 query 做向量/融合检索。kb_names 为空 =
	// 宿主全部启用中的知识库；top_k_fusion 为融合召回数，top_m_final 为最终
	// 保留条数（<=0 用宿主默认）。返回拼接后的上下文文本与检索结果 JSON 数组
	// （空结果时 context_text 为空、results_json 为 "[]"）。
	KBRetrieve(ctx context.Context, in *KBRetrieveRequest, opts ...grpc.CallOption) (*KBRetrieveResponse, error)
	// KBUploadFromURL 让宿主从 URL 拉取文档写入指定知识库并分块（chunk_size/
	// chunk_overlap <=0 用宿主默认）。
	KBUploadFromURL(ctx context.Context, in *KBUploadFromURLRequest, opts ...grpc.CallOption) (*Empty, error)
	// KBListKBs 列出宿主全部知识库元数据（每项为 KnowledgeBase 结构 JSON）。
	KBListKBs(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*KBListResponse, error)
	// ── 技能视图扩展（sandbox runtime 视图）──
	// ListSkillsV2 带过滤参数的技能列表：active_only 仅返回启用技能；runtime
	// 过滤运行时视图（"local"/"sandbox"/""=全部）；show_sandbox_path 返回
	// sandbox 路径而非宿主本地路径。复用既有 SkillsResponse。
	ListSkillsV2(ctx context.Context, in *ListSkillsV2Request, opts ...grpc.CallOption) (*SkillsResponse, error)
	// ── 文件令牌（file_token 文件服务）──
	// RegisterFileToken 把一个宿主侧文件路径登记为一次性令牌（timeout_sec
	// =0 用宿主默认 TTL），返回的 token 可供下游（如 sandbox runtime）凭
	// token 读取文件，避免暴露真实路径。
	RegisterFileToken(ctx context.Context, in *RegisterFileTokenRequest, opts ...grpc.CallOption) (*RegisterFileTokenResponse, error)
	// ── 插件定时任务（宿主 internal/cron）──
	// CronCreate 创建定时任务（job_type: cron / interval / once 等，run_once
	// + run_at(RFC3339) 用于一次性任务），返回宿主 Job 快照。
	CronCreate(ctx context.Context, in *CronCreateRequest, opts ...grpc.CallOption) (*CronJobResponse, error)
	// CronUpdate 按 job_id 更新任务字段（fields_json 指定更新字段集）。
	CronUpdate(ctx context.Context, in *CronUpdateRequest, opts ...grpc.CallOption) (*CronJobResponse, error)
	// CronDelete 删除指定定时任务。
	CronDelete(ctx context.Context, in *CronDeleteRequest, opts ...grpc.CallOption) (*Empty, error)
	// CronList 列出定时任务（job_type 空=全部）。
	CronList(ctx context.Context, in *CronListRequest, opts ...grpc.CallOption) (*CronJobsResponse, error)
	// CronRunNow 立即触发一次指定任务。
	CronRunNow(ctx context.Context, in *CronRunNowRequest, opts ...grpc.CallOption) (*Empty, error)
	// ── 宿主 MCP 读写桥接（只读列出 + 调用宿主侧 MCP 工具；插件自管 MCP
	// 不经此通道）──
	// McpListTools 列出宿主已连接 MCP server 的全部工具
	// （每项 {server, name, description, schema_json}）。
	McpListTools(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*McpToolsResponse, error)
	// McpCallTool 调用宿主侧 MCP 工具（server + tool_name + arguments_json），
	// 返回完整结果 JSON / 纯文本摘要 / 是否出错。
	McpCallTool(ctx context.Context, in *McpCallToolRequest, opts ...grpc.CallOption) (*McpCallToolResponse, error)
}

