// HostServiceServer is the server API for HostService service.
// All implementations must embed UnimplementedHostServiceServer
// for forward compatibility.
//
// HostService is served by the HOST and dialed by plugins for reverse calls.
type HostServiceServer interface {
	// CallAction forwards a platform API call (e.g. OneBot v11 call_action).
	CallAction(context.Context, *CallActionRequest) (*CallActionResponse, error)
	// SendMessage sends a message chain to a session (proactive/reactive send).
	SendMessage(context.Context, *SendMessageRequest) (*Empty, error)
	// RecallMessage recalls an already-sent message by platform message id.
	RecallMessage(context.Context, *RecallMessageRequest) (*Empty, error)
	// GetConfig returns the plugin's persisted config (plugins/<name>/config.json).
	GetConfig(context.Context, *GetConfigRequest) (*GetConfigResponse, error)
	// SetConfig persists the plugin's config (plugins/<name>/config.json).
	SetConfig(context.Context, *SetConfigRequest) (*Empty, error)
	// ChatLLM calls the host's default chat LLM provider and returns the reply.
	ChatLLM(context.Context, *ChatLLMRequest) (*ChatLLMResponse, error)
	// React adds an emoji reaction to a message (platforms supporting it).
	React(context.Context, *ReactRequest) (*Empty, error)
	// TextToImage renders text into an image (host t2i engine) and returns the
	// PNG bytes (base64). The plugin can then send it as an Image component.
	TextToImage(context.Context, *TextToImageRequest) (*TextToImageResponse, error)
	// HtmlRender renders an HTML template + data into an image via the host
	// (t2i remote preferred, local gg fallback). Returns PNG bytes (base64).
	HtmlRender(context.Context, *HtmlRenderRequest) (*HtmlRenderResponse, error)
	// ── 会话管理（对齐 Python AstrBot conversation_manager）──
	// 取会话当前 ID（umo 无会话时返回空串）。
	GetCurrConversationID(context.Context, *ConversationIDRequest) (*ConversationIDResponse, error)
	// 新建会话（设为当前）并返回其 ID。
	NewConversation(context.Context, *NewConversationRequest) (*ConversationIDResponse, error)
	// 按 umo+cid 取会话（create_if_not_exists 时不存在则新建）。
	GetConversation(context.Context, *GetConversationRequest) (*ConversationResponse, error)
	// 列出某 umo 的全部会话（无 umo 时列出全部）。
	GetConversations(context.Context, *GetConversationsRequest) (*ConversationsResponse, error)
	// 删除会话（按 umo+cid；cid 空时删除当前会话）。
	DeleteConversation(context.Context, *DeleteConversationRequest) (*Empty, error)
	// 切换当前会话（设置 umo 的 current cid）。
	SwitchConversation(context.Context, *SwitchConversationRequest) (*Empty, error)
	// 更新会话标题。
	UpdateConversationTitle(context.Context, *UpdateConversationTitleRequest) (*Empty, error)
	// 更新会话绑定的人格。
	UpdateConversationPersonaID(context.Context, *UpdateConversationPersonaRequest) (*Empty, error)
	// ── 人格管理（对齐 Python AstrBot persona_manager）──
	// 取全部人格。
	GetPersonas(context.Context, *Empty) (*PersonasResponse, error)
	// 取默认人格（按 umo 解析默认人格 id/name）。
	GetDefaultPersona(context.Context, *GetDefaultPersonaRequest) (*PersonaResponse, error)
	// 取文件夹树（嵌套结构）+ 全部人格。
	GetPersonaTree(context.Context, *Empty) (*PersonaTreeResponse, error)
	// 解析当前生效人格（会话/规则/默认的优先级合并）。
	ResolveSelectedPersona(context.Context, *ResolvePersonaRequest) (*ResolvePersonaResponse, error)
	// ── Provider 管理（对齐 Python AstrBot provider_manager）──
	// 列出全部 provider（按能力类型过滤，空=全部）。
	ListProviders(context.Context, *ListProvidersRequest) (*ProvidersResponse, error)
	// 取某 umo 当前使用的 provider（按能力类型）。
	GetUsingProvider(context.Context, *GetUsingProviderRequest) (*ProviderResponse, error)
	// 设置某 umo 的当前 provider。
	SetProvider(context.Context, *SetProviderRequest) (*Empty, error)
	// 取 provider 的模型列表。
	GetProviderModels(context.Context, *GetProviderModelsRequest) (*ProviderModelsResponse, error)
	// ── 插件/Star 管理（对齐 Python AstrBot star_manager）──
	// 列出全部已安装插件（Star 元数据）。
	GetPluginRegistry(context.Context, *Empty) (*StarsResponse, error)
	// 按插件名取 Star 元数据。
	GetStar(context.Context, *GetStarRequest) (*StarResponse, error)
	// 启用/禁用插件。
	SetPluginEnabled(context.Context, *SetPluginEnabledRequest) (*Empty, error)
	// 安装插件（git/url 源）。
	InstallPlugin(context.Context, *InstallPluginRequest) (*Empty, error)
	// UninstallPlugin 卸载插件。
	UninstallPlugin(context.Context, *UninstallPluginRequest) (*Empty, error)
	// ListCommandDescriptors 返回全部插件的命令描述符（含子命令/组/别名/
	// 权限/描述）。子进程架构下插件自身进程的 star 注册表只含自己的
	// handler，helps 类插件需经宿主查询全局指令列表。
	ListCommandDescriptors(context.Context, *Empty) (*CommandDescriptorsResponse, error)
	// ListPlatforms 返回全部已加载平台实例元数据（id/type/name/display_name/
	// config），供插件（如群分析类）发现平台并创建跨进程 bot 代理。
	ListPlatforms(context.Context, *Empty) (*PlatformsResponse, error)
	// ── 会话等待（SessionWaiter 跨进程喂入）──
	// 插件注册"等待某 umo 的下一条消息"（session_waiter.register_wait）。
	// 宿主收到该 umo 的消息时经 PluginService.FeedSessionWait 推送事件。
	RegisterSessionWait(context.Context, *RegisterSessionWaitRequest) (*RegisterSessionWaitResponse, error)
	// 插件注销等待（会话结束/超时）。
	UnregisterSessionWait(context.Context, *UnregisterSessionWaitRequest) (*Empty, error)
	// ── 桥接钩子（botpy/telegram 等兼容层）──
	RegisterBridgeHook(context.Context, *BridgeHookRequest) (*Empty, error)
	UnregisterBridgeHook(context.Context, *BridgeHookRequest) (*Empty, error)
	// ── 大文件 Blob 存储（P0-2）──────────────────────────────
	// 插件把大于 inline 阈值（1MB）的二进制交给宿主持久化，拿到一个受控
	// handle；后续经 ReadBlob 分块读取。宿主统一管理生命周期（TTL/GC），
	// 插件只传 handle，绝不传任意文件路径（防路径穿越）。
	CreateBlob(context.Context, *CreateBlobRequest) (*CreateBlobResponse, error)
	// ReadBlob 按 offset/limit 分块读，避免单次大缓冲。
	ReadBlob(context.Context, *ReadBlobRequest) (*ReadBlobResponse, error)
	GetBlobInfo(context.Context, *GetBlobInfoRequest) (*GetBlobInfoResponse, error)
	ReleaseBlob(context.Context, *ReleaseBlobRequest) (*Empty, error)
	// ── 技能（Skills，宿主 internal/skills 能力 → 插件可读可改）──
	// ListSkills 返回宿主技能管理器中的全部技能（SkillInfo JSON 列表）。
	ListSkills(context.Context, *Empty) (*SkillsResponse, error)
	// SetSkillActive 启用/禁用指定技能。
	SetSkillActive(context.Context, *SetSkillActiveRequest) (*Empty, error)
	// DeleteSkill 删除指定技能。
	DeleteSkill(context.Context, *DeleteSkillRequest) (*Empty, error)
	// ── 平台消息历史（宿主 db platform_message_history 表 → 插件可读可改）──
	// GetPlatformMessageHistory 按平台/用户取最近 n 条消息记录。
	GetPlatformMessageHistory(context.Context, *GetPMHistoryRequest) (*PMHistoryRecordsResponse, error)
	// InsertPlatformMessageHistory 插入一条平台消息记录。
	InsertPlatformMessageHistory(context.Context, *InsertPMHistoryRequest) (*PMHistoryRecordResponse, error)
	// UpdatePlatformMessageHistory 更新一条记录（content / llm_checkpoint_id）。
	UpdatePlatformMessageHistory(context.Context, *UpdatePMHistoryRequest) (*Empty, error)
	// DeletePlatformMessageHistory 按 ID 删除一条记录。
	DeletePlatformMessageHistory(context.Context, *DeletePMHistoryRequest) (*Empty, error)
	// ── 知识库（对齐宿主 internal/knowledgebase/manager.go）──
	// KBRetrieve 检索知识库：按 query 做向量/融合检索。kb_names 为空 =
	// 宿主全部启用中的知识库；top_k_fusion 为融合召回数，top_m_final 为最终
	// 保留条数（<=0 用宿主默认）。返回拼接后的上下文文本与检索结果 JSON 数组
	// （空结果时 context_text 为空、results_json 为 "[]"）。
	KBRetrieve(context.Context, *KBRetrieveRequest) (*KBRetrieveResponse, error)
	// KBUploadFromURL 让宿主从 URL 拉取文档写入指定知识库并分块（chunk_size/
	// chunk_overlap <=0 用宿主默认）。
	KBUploadFromURL(context.Context, *KBUploadFromURLRequest) (*Empty, error)
	// KBListKBs 列出宿主全部知识库元数据（每项为 KnowledgeBase 结构 JSON）。
	KBListKBs(context.Context, *Empty) (*KBListResponse, error)
	// ── 技能视图扩展（sandbox runtime 视图）──
	// ListSkillsV2 带过滤参数的技能列表：active_only 仅返回启用技能；runtime
	// 过滤运行时视图（"local"/"sandbox"/""=全部）；show_sandbox_path 返回
	// sandbox 路径而非宿主本地路径。复用既有 SkillsResponse。
	ListSkillsV2(context.Context, *ListSkillsV2Request) (*SkillsResponse, error)
	// ── 文件令牌（file_token 文件服务）──
	// RegisterFileToken 把一个宿主侧文件路径登记为一次性令牌（timeout_sec
	// =0 用宿主默认 TTL），返回的 token 可供下游（如 sandbox runtime）凭
	// token 读取文件，避免暴露真实路径。
	RegisterFileToken(context.Context, *RegisterFileTokenRequest) (*RegisterFileTokenResponse, error)
	// ── 插件定时任务（宿主 internal/cron）──
	// CronCreate 创建定时任务（job_type: cron / interval / once 等，run_once
	// + run_at(RFC3339) 用于一次性任务），返回宿主 Job 快照。
	CronCreate(context.Context, *CronCreateRequest) (*CronJobResponse, error)
	// CronUpdate 按 job_id 更新任务字段（fields_json 指定更新字段集）。
	CronUpdate(context.Context, *CronUpdateRequest) (*CronJobResponse, error)
	// CronDelete 删除指定定时任务。
	CronDelete(context.Context, *CronDeleteRequest) (*Empty, error)
	// CronList 列出定时任务（job_type 空=全部）。
	CronList(context.Context, *CronListRequest) (*CronJobsResponse, error)
	// CronRunNow 立即触发一次指定任务。
	CronRunNow(context.Context, *CronRunNowRequest) (*Empty, error)
	// ── 宿主 MCP 读写桥接（只读列出 + 调用宿主侧 MCP 工具；插件自管 MCP
	// 不经此通道）──
	// McpListTools 列出宿主已连接 MCP server 的全部工具
	// （每项 {server, name, description, schema_json}）。
	McpListTools(context.Context, *Empty) (*McpToolsResponse, error)
	// McpCallTool 调用宿主侧 MCP 工具（server + tool_name + arguments_json），
	// 返回完整结果 JSON / 纯文本摘要 / 是否出错。
	McpCallTool(context.Context, *McpCallToolRequest) (*McpCallToolResponse, error)
	mustEmbedUnimplementedHostServiceServer()
}

